// TD Composite TOP, operation Minimum (comp3 in the Ciurlionis mirror), followed by the
// alpha convention change Loom needs.
// TD takes the per-channel minimum of PREMULTIPLIED pixels, alpha included: the threshold
// matte (rgb = alpha = m, input 0) caps the AI picture (input 1, in More) at m and becomes
// its coverage, so TD stores (min(m, rgb), m). Loom carries straight alpha (SPEC V56), so
// that result is divided back out here; the Porter-Duff atop downstream multiplies it in
// again, and atop(front, painting) then reproduces TD's min(m, rgb) + painting * (1 - m).
struct Params {
  amount: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

fn secondAt(uv: vec2f) -> vec4f {
  let size = vec2i(textureDimensions(inputTexture1));
  let texel = clamp(vec2i(uv * vec2f(size)), vec2i(0), size - vec2i(1));
  return textureLoad(inputTexture1, texel, 0);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let matte = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let picture = secondAt(uv);
  let premultiplied = vec4f(picture.rgb * picture.a, picture.a);
  let keyed = min(matte, premultiplied);
  let straight = select(keyed.rgb / max(keyed.a, 1e-6), vec3f(0.0), keyed.a <= 0.0);
  // Amount 1 keys. 0 hands the AI picture through unkeyed.
  return mix(picture, vec4f(clamp(straight, vec3f(0.0), vec3f(1.0)), keyed.a), params.amount);
}

