// TD Composite TOP, operation Maximum (comp2 in drmbt's watercolor): per channel
// max(a, b), alpha included, as TD returns it. a is input 0 (the grained input), b is
// input 1 (the bled feedback, wired into More). This node is also what the feedback
// records, so the trail can only ever brighten the picture under it.
struct Params {
  amount: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

fn secondAt(uv: vec2f) -> vec4f {
  let size = vec2i(textureDimensions(inputTexture1));
  let texel = clamp(vec2i(uv * vec2f(size)), vec2i(0), size - vec2i(1));
  return textureLoad(inputTexture1, texel, 0);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let a = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let b = secondAt(uv);
  // Amount mixes from input 0 alone (0) to the full maximum (1).
  return mix(a, max(a, b), params.amount);
}

// TD Composite TOP, operation Soft Light (comp3 in drmbt's watercolor).
// Measured in TD 2025.33230 on two ramps: per channel (1 - 2b) * a^2 + 2b * a, the Pegtop
// form rather than the W3C one, where a is input 0 (the base: the drifted feedback) and
// b is input 1 (the blend: the grained input, wired into More). Alpha is input 0's.
struct Params {
  amount: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

fn secondAt(uv: vec2f) -> vec4f {
  let size = vec2i(textureDimensions(inputTexture1));
  let texel = clamp(vec2i(uv * vec2f(size)), vec2i(0), size - vec2i(1));
  return textureLoad(inputTexture1, texel, 0);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let a = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let b = secondAt(uv);
  let soft = ((vec3f(1.0) - (2.0 * b.rgb)) * a.rgb * a.rgb) + (2.0 * b.rgb * a.rgb);
  // Amount mixes from the base (0) to the full soft light (1).
  return vec4f(mix(a.rgb, soft, params.amount), a.a);
}
